/**
 * @file weaknet_cli.cpp
 * @brief weaknet-cli 运行时配置命令行工具
 *
 * 薄封装 D-Bus 调用 SetMonitorParam / GetMonitorParam，
 * 所有业务逻辑（校验、原子提交、持久化）在服务端实现。
 *
 * 用法：
 *   weaknet-cli get <monitor>              # 查询监控器参数（JSON）
 *   weaknet-cli set <key> <value>          # 设置参数
 *   weaknet-cli list                       # 列出可用监控器
 *
 * 示例：
 *   weaknet-cli set rtt.interval 5s
 *   weaknet-cli get rtt
 *   weaknet-cli get all
 */

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <unistd.h>

#include "weaknet_client.h"

static void printUsage(const char* prog) {
    fprintf(stderr,
        "用法：\n"
        "  %s get <target>               # 查询参数（JSON，支持各监控器及 active_probe, edge, server, all）\n"
        "  sudo %s set <key> <value>     # 设置参数（需 root，如 rtt.interval 5s, active_probe.targets ...）\n"
        "  %s list                       # 列出所有可查询/配置的目标\n"
        "  %s monitor list|status [name] # 查看监控插件运行状态（仅限插件化监控器）\n"
        "  sudo %s monitor enable|disable|restart <name> # 启停监控插件（需 root）\n"
        "  sudo %s monitor save          # 保存运行时启停状态（需 root）\n"
        "  %s events [--device <addr>] [--type <TYPE>]\n"
        "         [--start <ms>] [--end <ms>] [--limit <N>]\n"
        "                                 # 查询无线设备事件（JSON，只读）\n"
        "  %s incidents [--state <STATE>]\n"
        "         [--start <ms>] [--end <ms>] [--limit <N>]\n"
        "                                 # 查询区域级异常事件 SiteIncident（JSON，只读）\n"
        "  %s bt-traffic [--device <addr>]\n"
        "         [--start <ms>] [--end <ms>] [--limit <N>]\n"
        "                                 # 查询工业蓝牙 HCI ACL 数据通道流量指标（JSON，只读）\n"
        "  %s diagnosis [--ai]            # 查询网络诊断事实（--ai 联动端侧 RAG + 板载 Qwen 深度分析）\n"
        "  %s experience                  # 查询当前网络体验权威快照（NetworkExperience JSON，只读）\n"
        "  sudo %s action <action_id> [<key> <val>] # 执行白名单安全排查动作（仅限 root）\n"
        "\n"
        "事件类型（--type）：LINK_DISCONNECTED, LINK_DEGRADED, DEVICE_APPEARED, ...\n"
        "区域事件状态（--state）：OPEN, ONGOING, RESOLVED\n"
        "时间均为 Unix 毫秒，0 或省略表示不限；limit 默认 100，上限 10000\n"
        "\n"
        "监控器与参数目标：\n"
        "  插件监控器（支持 get/set 及 monitor 启停）：\n"
        "        rtt, rssi, tcp_loss, traffic, quality, bluetooth, bt_events, bt_hci_traffic,\n"
        "        dns, wifi_loss, http_latency, process_profiler, tcp_retrans,\n"
        "        tcp_conn, skb_drop, tcp_connect\n"
        "  常驻服务/全局组件（仅支持 get/set 调参，非插件）：\n"
        "        active_probe, edge, server, all\n"
        "\n"
        "示例：\n"
        "  sudo %s set rtt.interval 5s\n"
        "  %s get rtt\n"
        "  %s bt-traffic\n"
        "  %s bt-traffic --device 20:23:00:00:00:01\n"
        "  %s diagnosis\n"
        "  %s experience\n"
        "  sudo %s action CHECK_RESOLVER_CONFIG\n"
        "  sudo %s action PROBE_PUBLIC_RESOLVER resolver 223.5.5.5\n"
        "  %s list\n",
        prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog);
}

static bool callSet(const char* key, const char* value) {
    char err[256];
    if (!weaknet_set_monitor_param(key, value, err, sizeof(err))) {
        fprintf(stderr, "Set failed: %s\n", err);
        return false;
    }
    printf("ok\n");
    return true;
}

/// weaknet-cli events：查询规范化无线设备事件（只读）
/// 过滤参数全部可选；默认 limit=100（服务端上限 10000）
static bool callEvents(int argc, char** argv) {
    std::string device, type;
    int64_t start_ms = 0, end_ms = 0;
    int32_t limit = 100;

    for (int i = 2; i < argc; ++i) {
        auto need = [&](const char* opt) -> const char* {
            if (i + 1 >= argc) {
                fprintf(stderr, "缺少 %s 的值\n", opt);
                return nullptr;
            }
            return argv[++i];
        };
        if (strcmp(argv[i], "--device") == 0) {
            const char* v = need("--device"); if (!v) return false;
            device = v;
        } else if (strcmp(argv[i], "--type") == 0) {
            const char* v = need("--type"); if (!v) return false;
            type = v;
        } else if (strcmp(argv[i], "--start") == 0) {
            const char* v = need("--start"); if (!v) return false;
            start_ms = strtoll(v, nullptr, 10);
        } else if (strcmp(argv[i], "--end") == 0) {
            const char* v = need("--end"); if (!v) return false;
            end_ms = strtoll(v, nullptr, 10);
        } else if (strcmp(argv[i], "--limit") == 0) {
            const char* v = need("--limit"); if (!v) return false;
            limit = static_cast<int32_t>(strtol(v, nullptr, 10));
        } else {
            fprintf(stderr, "未知参数: %s\n", argv[i]);
            return false;
        }
    }

    // 上限 64KiB：limit 上限 10000 × 单条约 500B 最坏情况超出 64K，
    // 超出部分由服务端 limit 钳制约束（10000 条最坏约 5MB）——
    // 这里给 1MB 并提示用 --limit 收窄，避免栈上大数组
    std::vector<char> buf(1 << 20);
    char err[256];
    if (!weaknet_query_device_events(device.c_str(), type.c_str(),
                                     start_ms, end_ms, limit,
                                     buf.data(), buf.size(),
                                     err, sizeof(err))) {
        fprintf(stderr, "事件查询失败: %s\n", err);
        return false;
    }
    printf("%s\n", buf.data());
    return true;
}

/// weaknet-cli incidents：查询区域级异常事件（只读，Phase 3a）
/// 过滤参数全部可选；默认 limit=100（服务端上限 10000）
static bool callIncidents(int argc, char** argv) {
    std::string state;
    int64_t start_ms = 0, end_ms = 0;
    int32_t limit = 100;

    for (int i = 2; i < argc; ++i) {
        auto need = [&](const char* opt) -> const char* {
            if (i + 1 >= argc) {
                fprintf(stderr, "缺少 %s 的值\n", opt);
                return nullptr;
            }
            return argv[++i];
        };
        if (strcmp(argv[i], "--state") == 0) {
            const char* v = need("--state"); if (!v) return false;
            state = v;
        } else if (strcmp(argv[i], "--start") == 0) {
            const char* v = need("--start"); if (!v) return false;
            start_ms = strtoll(v, nullptr, 10);
        } else if (strcmp(argv[i], "--end") == 0) {
            const char* v = need("--end"); if (!v) return false;
            end_ms = strtoll(v, nullptr, 10);
        } else if (strcmp(argv[i], "--limit") == 0) {
            const char* v = need("--limit"); if (!v) return false;
            limit = static_cast<int32_t>(strtol(v, nullptr, 10));
        } else {
            fprintf(stderr, "未知参数: %s\n", argv[i]);
            return false;
        }
    }

    // 与 callEvents 同一理由的 1MB 缓冲：区域事件单条含受影响设备清单，
    // 比设备事件更大；超出部分由服务端 limit 钳制约束。
    std::vector<char> buf(1 << 20);
    char err[256];
    if (!weaknet_query_site_incidents(state.c_str(), start_ms, end_ms, limit,
                                      buf.data(), buf.size(), err, sizeof(err))) {
        fprintf(stderr, "区域事件查询失败: %s\n", err);
        return false;
    }
    printf("%s\n", buf.data());
    return true;
}

/// weaknet-cli bt-traffic：查询工业蓝牙 HCI ACL 数据通道历史指标（只读，Phase 1b）
static bool callBtTraffic(int argc, char** argv) {
    std::string device;
    int64_t start_ms = 0, end_ms = 0;
    int32_t limit = 100;

    for (int i = 2; i < argc; ++i) {
        auto need = [&](const char* opt) -> const char* {
            if (i + 1 >= argc) {
                fprintf(stderr, "缺少 %s 的值\n", opt);
                return nullptr;
            }
            return argv[++i];
        };
        if (strcmp(argv[i], "--device") == 0) {
            const char* v = need("--device"); if (!v) return false;
            device = v;
        } else if (strcmp(argv[i], "--start") == 0) {
            const char* v = need("--start"); if (!v) return false;
            start_ms = strtoll(v, nullptr, 10);
        } else if (strcmp(argv[i], "--end") == 0) {
            const char* v = need("--end"); if (!v) return false;
            end_ms = strtoll(v, nullptr, 10);
        } else if (strcmp(argv[i], "--limit") == 0) {
            const char* v = need("--limit"); if (!v) return false;
            limit = static_cast<int32_t>(strtol(v, nullptr, 10));
        } else {
            fprintf(stderr, "未知参数: %s\n", argv[i]);
            return false;
        }
    }

    std::vector<char> buf(1 << 20);
    char err[256];
    if (!weaknet_query_bt_data_path(device.c_str(), start_ms, end_ms, limit,
                                    buf.data(), buf.size(), err, sizeof(err))) {
        fprintf(stderr, "蓝牙数传指标查询失败: %s\n", err);
        return false;
    }
    printf("%s\n", buf.data());
    return true;
}

static bool callLifecycle(const char* operation, const char* monitor) {
    char buf[8192];
    char err[256];
    bool ok = false;
    if (strcmp(operation, "status") == 0) {
        ok = monitor ? weaknet_get_monitor_status(monitor, buf, sizeof(buf), err, sizeof(err))
                     : weaknet_list_monitors(buf, sizeof(buf), err, sizeof(err));
    } else if (strcmp(operation, "enable") == 0) {
        ok = weaknet_enable_monitor(monitor, buf, sizeof(buf), err, sizeof(err));
    } else if (strcmp(operation, "disable") == 0) {
        ok = weaknet_disable_monitor(monitor, buf, sizeof(buf), err, sizeof(err));
    } else if (strcmp(operation, "restart") == 0) {
        ok = weaknet_restart_monitor(monitor, buf, sizeof(buf), err, sizeof(err));
    }
    if (ok) printf("%s\n", buf);
    else fprintf(stderr, "Monitor operation failed: %s\n", err);
    return ok;
}

static bool callGet(const char* monitor) {
    char buf[8192];
    char err[256];
    if (!weaknet_get_monitor_param(monitor, buf, sizeof(buf), err, sizeof(err))) {
        fprintf(stderr, "Get failed: %s\n", err);
        return false;
    }
    printf("%s\n", buf);
    return true;
}

static bool callSaveOverrides() {
    char buf[8192];
    char err[256];
    if (!weaknet_save_monitor_overrides(buf, sizeof(buf), err, sizeof(err))) {
        fprintf(stderr, "Save monitor overrides failed: %s\n", err);
        return false;
    }
    printf("%s\n", buf);
    return true;
}

static bool callDiagnosis(bool enable_ai = false) {
    std::vector<char> buf(64 * 1024);
    char err[256];
    if (!weaknet_get_diagnosis(buf.data(), buf.size(), err, sizeof(err))) {
        fprintf(stderr, "GetDiagnosis 失败: %s\n", err);
        return false;
    }

    if (!enable_ai) {
        printf("%s\n", buf.data());
        return true;
    }

    // --ai 标志：调用本地端侧 Edge RAG (Python 脚本桥接板载 Qwen-0.5B 与知识库)
    std::vector<char> exp_buf(64 * 1024);
    if (!weaknet_get_network_experience(exp_buf.data(), exp_buf.size(), err, sizeof(err))) {
        fprintf(stderr, "获取网络体验快照失败，降级输出原始诊断: %s\n", err);
        printf("%s\n", buf.data());
        return true;
    }

    // 优先调用 /home/radxa/weaknet/edge_network_rag.py
    const char* script_candidates[] = {
        "/home/radxa/weaknet/edge_network_rag.py",
        "./edge_network_rag.py",
        "../edge_network_rag.py"
    };

    const char* chosen_script = nullptr;
    for (const char* path : script_candidates) {
        if (access(path, R_OK) == 0) {
            chosen_script = path;
            break;
        }
    }

    if (!chosen_script) {
        fprintf(stderr, "⚠️ 未找到端侧 RAG 脚本，降级输出基础诊断\n");
        printf("%s\n", buf.data());
        return true;
    }

    std::string cmd = std::string("python3 ") + chosen_script;
    FILE* pipe = popen(cmd.c_str(), "w");
    if (!pipe) {
        fprintf(stderr, "⚠️ 启动端侧 RAG 进程失败\n");
        printf("%s\n", buf.data());
        return true;
    }

    fwrite(exp_buf.data(), 1, strlen(exp_buf.data()), pipe);
    pclose(pipe);
    return true;
}

static bool callExperience() {
    std::vector<char> buf(64 * 1024);
    char err[256];
    if (!weaknet_get_network_experience(buf.data(), buf.size(), err, sizeof(err))) {
        fprintf(stderr, "GetNetworkExperience 失败: %s\n", err);
        return false;
    }
    printf("%s\n", buf.data());
    return true;
}

static bool callAction(int argc, char** argv) {
    if (argc < 3 || argc > 5) {
        printUsage(argv[0]);
        return false;
    }
    const char* action_id = argv[2];
    const char* param_key = (argc >= 4) ? argv[3] : "";
    const char* param_val = (argc >= 5) ? argv[4] : "";
    std::vector<char> buf(64 * 1024);
    char err[256];
    if (!weaknet_execute_action(action_id, param_key, param_val, buf.data(), buf.size(), err, sizeof(err))) {
        fprintf(stderr, "ExecuteAction 失败: %s\n", err);
        return false;
    }
    printf("%s\n", buf.data());
    return true;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        printUsage(argv[0]);
        return 1;
    }

    // 初始化客户端
    if (!weaknet_init()) {
        fprintf(stderr, "weaknet_init 失败\n");
        return 1;
    }

    const char* cmd = argv[1];
    bool ok = false;

    if (strcmp(cmd, "get") == 0) {
        if (argc != 3) {
            printUsage(argv[0]);
            return 1;
        }
        ok = callGet(argv[2]);
    } else if (strcmp(cmd, "set") == 0) {
        if (argc != 4) {
            printUsage(argv[0]);
            return 1;
        }
        ok = callSet(argv[2], argv[3]);
    } else if (strcmp(cmd, "monitor") == 0) {
        if (argc < 3 || argc > 4) {
            printUsage(argv[0]);
            return 1;
        }
        const char* operation = argv[2];
        const char* monitor = argc == 4 ? argv[3] : nullptr;
        if (strcmp(operation, "list") == 0 || strcmp(operation, "status") == 0) {
            if (strcmp(operation, "list") == 0 && monitor) {
                printUsage(argv[0]);
                return 1;
            }
            ok = callLifecycle(strcmp(operation, "list") == 0 ? "status" : operation, monitor);
        } else if (strcmp(operation, "save") == 0 && !monitor) {
            ok = callSaveOverrides();
        } else if ((strcmp(operation, "enable") == 0 || strcmp(operation, "disable") == 0 ||
                    strcmp(operation, "restart") == 0) && monitor) {
            ok = callLifecycle(operation, monitor);
        } else {
            printUsage(argv[0]);
            return 1;
        }
    } else if (strcmp(cmd, "events") == 0) {
        ok = callEvents(argc, argv);
    } else if (strcmp(cmd, "incidents") == 0) {
        ok = callIncidents(argc, argv);
    } else if (strcmp(cmd, "bt-traffic") == 0) {
        ok = callBtTraffic(argc, argv);
    } else if (strcmp(cmd, "diagnosis") == 0) {
        bool enable_ai = (argc >= 3 && strcmp(argv[2], "--ai") == 0);
        ok = callDiagnosis(enable_ai);
    } else if (strcmp(cmd, "experience") == 0) {
        ok = callExperience();
    } else if (strcmp(cmd, "action") == 0) {
        ok = callAction(argc, argv);
    } else if (strcmp(cmd, "list") == 0) {
        // 必须与 serializers 端的有效名集合保持一致（weaknet_config.cpp 的
        // serializeMonitorJson）。此前这里漏了 skb_drop / tcp_connect /
        // active_probe / edge——它们可以被 `set` 但 `list` 不显示，用户无从发现。
        printf("rtt\nrssi\ntcp_loss\ntraffic\nquality\n"
               "bluetooth\ndns\nwifi_loss\nhttp_latency\nprocess_profiler\n"
               "tcp_retrans\ntcp_conn\nskb_drop\ntcp_connect\ntcp_rtt\n"
               "active_probe\nedge\nserver\nall\n");
        ok = true;
    } else {
        fprintf(stderr, "未知命令: %s\n", cmd);
        printUsage(argv[0]);
        return 1;
    }

    weaknet_cleanup();
    return ok ? 0 : 1;
}

/**
 * @file common.hpp
 * @brief D-Bus 服务常量与全局配置定义
 *
 * 集中管理服务标识（bus name / object path / interface）、
 * 方法名、信号名以及运行时可配置的路径常量。
 * 路径常量支持通过环境变量覆盖，便于交叉编译部署和测试。
 *
 * 线程安全：本文件所有静态/inline 常量在编译期初始化，
 * 首次访问时求值（函数体风格的 lambda），无需额外锁。
 */

#pragma once

#include <string>

namespace weaknet_dbus {

// ==================== D-Bus 基础标识 ====================
// 这三个值共同决定了 D-Bus 服务的寻址三元组：BusName.ObjectPath.Interface
// 客户端必须使用完全相同的值才能正确连接到服务端

static constexpr const char kBusName[]     = "com.example.WeakNet";   ///< 服务名（唯一，由 dbus_bus_request_name 注册）
static constexpr const char kObjectPath[]  = "/com/example/WeakNet"; ///< 对象路径（类似文件系统，必须以 / 开头）
static constexpr const char kInterface[]    = "com.example.WeakNet"; ///< 接口名（方法和信号的命名空间）

// ==================== D-Bus 方法名 ====================
// 每个方法对应 DbusService 中一个 handleXxx 成员函数实现
// 客户端通过 dbus_message_new_method_call(..., kMethodXxx) 发起调用

static constexpr const char kMethodListInterfaces[]          = "ListInterfaces";      ///< 返回所有可用接口名的字符串数组
static constexpr const char kMethodGetInterfaces[]           = "GetInterfaces";      ///< ListInterfaces 的同义名（向后兼容）
static constexpr const char kMethodHealthCheck[]            = "HealthCheck";        ///< 执行网络健康检查，返回 JSON 格式诊断结果
static constexpr const char kMethodGetDiagnosis[]          = "GetDiagnosis";       ///< 查询端侧确定性机器诊断事实（DiagnosisFacts JSON）
static constexpr const char kMethodExecuteAction[]          = "ExecuteAction";      ///< 通过 ActionRegistry 执行安全动作（posix_spawn 隔离）
static constexpr const char kMethodPing[]                   = "Ping";               ///< 对指定主机执行 ICMP Ping，返回延迟和丢包
static constexpr const char kMethodGetBluetoothDevices[]    = "GetBluetoothDevices";///< 返回已发现蓝牙设备列表（BlueZ D-Bus）
static constexpr const char kMethodGetBluetoothAdapter[]     = "GetBluetoothAdapter";///< 返回蓝牙适配器状态（是否可用、是否在连接中）
static constexpr const char kMethodGetBluetoothAudioQuality[] = "GetBluetoothAudioQuality"; ///< 查询蓝牙 A2DP 音频质量与 eBPF 融合诊断（JSON）
static constexpr const char kMethodGetCoexistenceConflict[]  = "GetCoexistenceConflict";
static constexpr const char kMethodGetNetworkExperience[] = "GetNetworkExperience";   ///< 查询 Wi-Fi 与蓝牙 2.4GHz 共存冲突与根因分析（JSON）
static constexpr const char kMethodGetDnsStats[]            = "GetDnsStats";        ///< 查询 DNS eBPF 监控的最近统计（平均延迟、超时率）
static constexpr const char kMethodGetWifiLossStats[]        = "GetWifiLossStats";   ///< 查询 Wi-Fi eBPF 丢包归因（按 ifindex）
static constexpr const char kMethodGetHttpLatencyStats[]    = "GetHttpLatencyStats";///< 查询 HTTP eBPF 请求延迟统计（p50/p99/慢请求）
static constexpr const char kMethodGetProcessProfiling[]    = "GetProcessProfiling";///< 查询 eBPF 进程网络画像（Top N 带宽进程）
static constexpr const char kMethodGetSkbDropStats[]        = "GetSkbDropStats";    ///< 查询 Socket/skb 丢包原因精确归因统计（JSON）
static constexpr const char kMethodGetTcpRttStats[]         = "GetTcpRttStats";     ///< 查询被动 TCP RTT 与拥塞统计（JSON）
static constexpr const char kMethodGetEbpfMonitorHealth[]   = "GetEbpfMonitorHealth";///< 查询所有 eBPF 监控器健康状态（是否成功加载）
static constexpr const char kMethodGetHistory[]              = "GetHistory";         ///< 查询 SQLite 历史快照（支持时间范围和网卡过滤）
static constexpr const char kMethodQueryDeviceEvents[]      = "QueryDeviceEvents";  ///< 查询规范化无线设备事件（时间范围/设备/类型过滤）
static constexpr const char kMethodQueryBtDataPath[]        = "QueryBtDataPath";    ///< 查询工业蓝牙数传链路流量指标（Phase 1b：时间/设备过滤）
static constexpr const char kMethodQuerySiteIncidents[]     = "QuerySiteIncidents"; ///< 查询区域级异常事件 SiteIncident（Phase 3a：区域层）
static constexpr const char kMethodSetMonitorParam[]         = "SetMonitorParam";   ///< 运行时设置监控器参数（白名单校验+原子提交）
static constexpr const char kMethodGetMonitorParam[]         = "GetMonitorParam";   ///< 查询监控器当前参数（JSON 格式）
static constexpr const char kMethodListMonitors[]             = "ListMonitors";
static constexpr const char kMethodGetMonitorStatus[]         = "GetMonitorStatus";
static constexpr const char kMethodEnableMonitor[]            = "EnableMonitor";
static constexpr const char kMethodDisableMonitor[]           = "DisableMonitor";
static constexpr const char kMethodRestartMonitor[]           = "RestartMonitor";
static constexpr const char kMethodSaveMonitorOverrides[]     = "SaveMonitorOverrides";

// ==================== 信号名 ====================
// 服务端主动向订阅客户端推送事件。客户端通过 dbus_bus_add_match 过滤感兴趣的信号

static constexpr const char kSignalChanged[]                = "Changed";                ///< 通用变化信号（文本消息 + 计数器，旧版兼容）
static constexpr const char kSignalInterfaceChanged[]       = "InterfaceChanged";       ///< 网卡添加/删除事件
static constexpr const char kSignalConnectionModeChanged[]  = "ConnectionModeChanged";  ///< 当前上网网卡切换事件
static constexpr const char kSignalNetworkQualityChanged[]  = "NetworkQualityChanged";  ///< 综合网络质量（Excellent/Good/Fair/Poor）变化
static constexpr const char kSignalBluetoothDeviceChanged[] = "BluetoothDeviceChanged"; ///< 蓝牙设备出现/消失/状态变化
static constexpr const char kSignalMonitorStateChanged[]    = "MonitorStateChanged";
///< eBPF 监控器聚合指标推送（JSON：monitor + 该监控器的关键统计 + 驱逐差分）
static constexpr const char kSignalEbpfMonitorStats[]       = "EbpfMonitorStats";

// ==================== 运行时路径常量 ====================

/// SQLite 历史数据持久化路径解析函数。
/// 见 kDatabasePath 注释。
inline std::string resolveDatabasePath(const std::string& cfg_data_dir) {
    if (!cfg_data_dir.empty()) {
        return cfg_data_dir + "/history.db";
    }
    const char* env = std::getenv("WEAKNET_DATA_DIR");
    if (env && *env) {
        return std::string(env) + "/history.db";
    }
    return std::string("/home/radxa/weaknet/data") + "/history.db";
}

/// 网络代次状态文件路径。与 history.db 同目录 —— 二者都是"这台设备的
/// 持久身份"，放在一起才能保证备份/迁移时不会只带走一半。
inline std::string resolveNetworkEpochPath(const std::string& cfg_data_dir) {
    return resolveDatabasePath(cfg_data_dir).substr(
               0, resolveDatabasePath(cfg_data_dir).size() - std::string("history.db").size()) +
           "network-epoch";
}

/// 默认流量分析接口名。空字符串 "" 表示自动选择当前活动接口
/// 可通过 WEAKNET_TRAFFIC_IFACE 覆盖（如 WEAKNET_TRAFFIC_IFACE=eth1 强制分析指定网卡）
inline const std::string kDefaultTrafficInterface = []() {
    const char* env = std::getenv("WEAKNET_TRAFFIC_IFACE");
    return env ? env : "";
}();

/// Changed 信号序列化输出文件路径
/// 使用 $XDG_RUNTIME_DIR 私有目录（通常是 /run/user/$UID），防符号链接攻击
/// 若 XDG_RUNTIME_DIR 未设置则退回到 /tmp（开发环境兼容）
inline const std::string kSignalSerializedFile = []() {
    const char* xdg = std::getenv("XDG_RUNTIME_DIR");
    return std::string(xdg ? xdg : "/tmp") + "/weaknet/signal_changed.bin";
}();

}  // namespace weaknet_dbus

